#!/usr/bin/env bash
set -euo pipefail
source "$(dirname "$0")/harness_lock.sh"
phase=; current=; next=; freeze_plan=0; refresh_plan=0; freeze_implementation=0; adopted=()
while [[ $# -gt 0 ]]; do case "$1" in --phase) phase=${2:?}; shift ;; --current-step) current=${2:?}; shift ;; --next-step) next=${2:?}; shift ;; --freeze-planning-baseline) freeze_plan=1 ;; --refresh-planning-baseline) refresh_plan=1 ;; --freeze-implementation-base) freeze_implementation=1 ;; --adopt-path) adopted+=("${2:?}"); shift ;; *) echo "[ERR] unknown option: $1" >&2; exit 2 ;; esac; shift; done
(( freeze_plan + refresh_plan <= 1 )) || { echo '[ERR] initial freeze and planning-baseline refresh are mutually exclusive' >&2; exit 2; }
if [[ "$refresh_plan" -eq 1 ]]; then
  [[ "$freeze_implementation" -eq 0 && "${#adopted[@]}" -eq 0 ]] || { echo '[ERR] planning refresh cannot move the implementation base or adopt new paths' >&2; exit 2; }
  [[ -z "$phase" || "$phase" == implementing ]] || { echo '[ERR] planning refresh resumes at phase=implementing' >&2; exit 2; }
  phase=implementing; [[ -n "$current" ]] || current=planning-reapproved; [[ -n "$next" ]] || next='Resume the first unchecked task, or begin Evaluation when all tasks are complete'
fi
for value in "$phase" "$current" "$next"; do [[ "$value" != *$'\n'* && "$value" != *$'\r'* ]] || { echo '[ERR] snapshot cursor values must be single-line' >&2; exit 2; }; done
harness_lock_acquire snapshot-update ""; harness_require_no_archive_failure; active=$(harness_active_optional); [[ -z "$active" ]] || harness_lock_bind_change "$active"; args=(); [[ -z "$phase" ]] || args+=("phase=$phase"); [[ -z "$current" ]] || args+=("current_step=$current"); [[ -z "$next" ]] || args+=("next_step=$next")
if [[ -n "$active" ]]; then isolation_status=$(harness_isolation_node status "$active"); if [[ "$(node -p "JSON.parse(process.argv[1]).worktree_kind" "$isolation_status")" == linked && "$(node -p "JSON.parse(process.argv[1]).local_lease||''" "$isolation_status")" != '' ]]; then [[ "$freeze_plan" -eq 0 && "$refresh_plan" -eq 0 && "$freeze_implementation" -eq 0 && "${#adopted[@]}" -eq 0 && ( -z "$phase" || "$phase" == implementing ) ]] || { echo '[ERR] isolation pilot permits only implementing cursor updates; planning/base/ownership changes stay in the coordinator worktree' >&2; exit 4; }; fi; fi
if [[ -n "$active" && ( -n "$phase" || -n "$current" || -n "$next" || "$freeze_plan" -eq 1 || "$refresh_plan" -eq 1 || "$freeze_implementation" -eq 1 || "${#adopted[@]}" -gt 0 ) ]]; then
  local_snapshot="openspec/changes/$active/harness/ai_snapshot.json"; [[ -f "$local_snapshot" && ! -L "$local_snapshot" ]] || { echo "[ERR] local snapshot missing" >&2; exit 6; }
  snapshot_version=$(node -p "JSON.parse(require('fs').readFileSync(process.argv[1])).schema_version" "$local_snapshot"); [[ "$snapshot_version" == 2 || "$snapshot_version" == 3 || "$snapshot_version" == 4 ]] || { echo '[ERR] unsupported local snapshot schema' >&2; exit 6; }
  planned=; planned_change=; planned_policy=; planned_integration=; implementation=; current_base=$(scripts/source_fingerprint.sh --kind base-specs --change "$active")
  if [[ "$snapshot_version" == 3 || "$snapshot_version" == 4 ]]; then
    planning_json=$(scripts/source_fingerprint.sh --kind planning --change "$active" --json) || { echo '[ERR] canonical TDD/integration policy or planning artifacts are invalid' >&2; exit 6; }
    current_change=$(node -p "JSON.parse(require('fs').readFileSync(process.argv[1])).planning_fingerprint" /dev/stdin <<<"$planning_json")
    current_policy=$(node -p "JSON.parse(require('fs').readFileSync(process.argv[1])).tdd_policy_sha256" /dev/stdin <<<"$planning_json")
    if [[ "$snapshot_version" == 4 ]]; then current_integration=$(node -p "JSON.parse(require('fs').readFileSync(process.argv[1])).integration_completeness_sha256" /dev/stdin <<<"$planning_json"); [[ "$current_integration" =~ ^sha256:[0-9a-f]{64}$ ]] || { echo '[ERR] Integration Completeness planning digest is invalid' >&2; exit 6; }; else current_integration=; fi
  else
    current_change=; current_policy=; current_integration=
  fi
  for p in "${adopted[@]}"; do [[ "$p" != /* && "$p" != *'..'* && "$p" != *$'\n'* ]] || { echo "[ERR] invalid adopted path: $p" >&2; exit 2; }; git diff --quiet HEAD -- "$p" 2>/dev/null && [[ -z "$(git ls-files --others --exclude-standard -- "$p")" ]] && { echo "[ERR] adopted path is not a pre-existing dirty path: $p" >&2; exit 6; }; done
  if [[ "$refresh_plan" -eq 1 ]]; then
    node - "$local_snapshot" "openspec/changes/$active/harness/verification.json" "openspec/changes/$active/harness/integration-upgrade-v3.json" "openspec/changes/$active/harness/evaluation-baseline.json" ai_snapshot.json "$active" <<'NODE' || { echo '[ERR] planning refresh requires an approved baseline or the exact committed v3-upgrade target, a safe frozen implementation base, no evidence/Evaluation and no archive recovery' >&2; exit 6; }
const fs=require('fs'),crypto=require('crypto'),path=require('path');
const [snapshotFile,verificationFile,journalFile,baselineFile,rootFile,change]=process.argv.slice(2),safe=f=>{const s=fs.lstatSync(f);if(!s.isFile()||s.isSymbolicLink())process.exit(1);return JSON.parse(fs.readFileSync(f))},sha=b=>'sha256:'+crypto.createHash('sha256').update(b).digest('hex'),snapshotRaw=fs.readFileSync(snapshotFile),verificationRaw=fs.readFileSync(verificationFile),snapshot=JSON.parse(snapshotRaw),root=safe(rootFile);
if(![2,3,4].includes(snapshot.schema_version)||typeof snapshot.implementation_base_commit!=='string'||!/^[0-9a-f]{40,64}$/.test(snapshot.implementation_base_commit)||root.active_change!==change||root.phase==='archive_failed')process.exit(1);
const normalApproved=!!snapshot.planned_base_specs_fingerprint&&(snapshot.schema_version<3||!!snapshot.planned_change_fingerprint&&!!snapshot.planned_tdd_policy_sha256)&&(snapshot.schema_version!==4||!!snapshot.planned_integration_completeness_sha256);
let committedUpgradeTarget=false;
if(!normalApproved&&snapshot.schema_version===4&&fs.existsSync(journalFile)){
  const journal=safe(journalFile),verification=JSON.parse(verificationRaw),planned=[snapshot.planned_base_specs_fingerprint,snapshot.planned_change_fingerprint,snapshot.planned_tdd_policy_sha256,snapshot.planned_integration_completeness_sha256],harnessDir=path.dirname(snapshotFile),forbidden=['integration-surface-report.json','evaluation-baseline.json','evaluation-command-ledger.json','evaluation.json','evaluations'];
  committedUpgradeTarget=journal.schema_version===1&&journal.change_name===change&&journal.status==='committed'&&planned.every(v=>v===null)&&snapshot.planning_approved_at===null&&sha(snapshotRaw)===journal.target_snapshot_sha256&&sha(verificationRaw)===journal.target_verification_sha256&&verification.schema_version===3&&verification.change_name===change&&Array.isArray(verification.tasks)&&verification.tasks.length===0&&forbidden.every(name=>!fs.existsSync(path.join(harnessDir,name)))&&!/^- \[[xX]\] \d/m.test(fs.readFileSync(path.join(harnessDir,'..','tasks.md'),'utf8'));
}
if(!normalApproved&&!committedUpgradeTarget)process.exit(1);if(fs.existsSync(baselineFile)){const baseline=safe(baselineFile);if(baseline.status==='in_progress')process.exit(1)}
NODE
    implementation_base=$(node -p "JSON.parse(require('fs').readFileSync(process.argv[1])).implementation_base_commit" "$local_snapshot")
    [[ "$(git rev-parse --verify "$implementation_base^{commit}" 2>/dev/null)" == "$implementation_base" ]] && git merge-base --is-ancestor "$implementation_base" HEAD || { echo '[ERR] frozen implementation base is no longer a valid ancestor; recover it before re-planning' >&2; exit 6; }
  fi
  if [[ "$freeze_plan" -eq 1 || "$refresh_plan" -eq 1 ]]; then planned=$current_base; planned_change=$current_change; planned_policy=$current_policy; planned_integration=$current_integration; fi
  if [[ "$freeze_implementation" -eq 1 ]]; then
    [[ -z "$phase" || "$phase" == implementing ]] || { echo '[ERR] freezing the implementation base requires phase=implementing' >&2; exit 2; }
    recorded_plan=$(node -p "JSON.parse(require('fs').readFileSync(process.argv[1])).planned_base_specs_fingerprint||''" "$local_snapshot")
    intended_plan=$recorded_plan; [[ "$freeze_plan" -eq 0 ]] || intended_plan=$current_base
    [[ -n "$intended_plan" && "$intended_plan" == "$current_base" ]] || { echo '[ERR] planned base specs missing or stale; explicitly revise and re-approve the plan' >&2; exit 6; }
    if [[ "$snapshot_version" == 3 || "$snapshot_version" == 4 ]]; then
      recorded_change=$(node -p "JSON.parse(require('fs').readFileSync(process.argv[1])).planned_change_fingerprint||''" "$local_snapshot"); recorded_policy=$(node -p "JSON.parse(require('fs').readFileSync(process.argv[1])).planned_tdd_policy_sha256||''" "$local_snapshot")
      intended_change=$recorded_change; intended_policy=$recorded_policy; if [[ "$freeze_plan" -eq 1 ]]; then intended_change=$current_change; intended_policy=$current_policy; fi
      [[ -n "$intended_change" && "$intended_change" == "$current_change" && -n "$intended_policy" && "$intended_policy" == "$current_policy" ]] || { echo '[ERR] approved planning or TDD policy fingerprint is missing/stale' >&2; exit 6; }
      if [[ "$snapshot_version" == 4 ]]; then recorded_integration=$(node -p "JSON.parse(require('fs').readFileSync(process.argv[1])).planned_integration_completeness_sha256||''" "$local_snapshot"); intended_integration=$recorded_integration; [[ "$freeze_plan" -eq 0 ]] || intended_integration=$current_integration; [[ -n "$intended_integration" && "$intended_integration" == "$current_integration" ]] || { echo '[ERR] approved Integration Completeness fingerprint is missing/stale' >&2; exit 6; }; fi
    fi
    implementation=$(git rev-parse --verify HEAD 2>/dev/null) || { echo "[ERR] implementation requires a HEAD commit" >&2; exit 4; }
    dirty=$(mktemp "${TMPDIR:-/tmp}/autoai-preexisting.XXXXXX"); { git diff --name-only -z HEAD; git ls-files --others --exclude-standard -z; } > "$dirty"
    node - "$dirty" "$local_snapshot" "${adopted[@]}" <<'NODE'
const fs=require('fs'),policy=require(process.cwd()+'/scripts/manifest_policy.js').loadManifest();const [dirtyFile,snapshotFile,...added]=process.argv.slice(2),d=JSON.parse(fs.readFileSync(snapshotFile)),adopted=new Set([...(d.adopted_preexisting_paths||[]),...added]),paths=fs.readFileSync(dirtyFile).toString('utf8').split('\0').filter(Boolean),missing=[...new Set(paths.filter(p=>!policy.isManaged(p)&&!adopted.has(p)))];if(missing.length){console.error('[ERR] pre-existing dirty paths need explicit --adopt-path: '+missing.join(', '));process.exit(6)}
NODE
    rm -f -- "$dirty"
  fi
  if [[ "$freeze_plan" -eq 1 || "$refresh_plan" -eq 1 || "$freeze_implementation" -eq 1 ]]; then
    if [[ "$snapshot_version" == 4 ]]; then AUTOAI_LOCK_TOKEN="$HARNESS_OWNED_TOKEN" AUTOAI_PARENT_PURPOSE=snapshot-update scripts/integration_surface_check.sh "$active" --plan-check --json >/dev/null || { echo '[ERR] Integration Completeness planning check failed; no baseline was written' >&2; exit 6; }; fi
    AUTOAI_LOCK_TOKEN="$HARNESS_OWNED_TOKEN" AUTOAI_PARENT_PURPOSE=snapshot-update scripts/evaluator_check.sh --plan "$active" >/dev/null || { echo '[ERR] coding readiness failed; no planning or implementation baseline was written' >&2; exit 6; }
  fi
  node - "$local_snapshot" "$planned" "$planned_change" "$planned_policy" "$planned_integration" "$implementation" "$current_base" "$current_change" "$current_policy" "$current_integration" "$phase" "$current" "$next" "$refresh_plan" "${adopted[@]}" <<'NODE'
const fs=require('fs'),path=require('path');const [file,planned,plannedChange,plannedPolicy,plannedIntegration,base,currentBase,currentChange,currentPolicy,currentIntegration,phase,current,next,refresh,...adopted]=process.argv.slice(2),st=fs.lstatSync(file),d=JSON.parse(fs.readFileSync(file)),v2=['schema_version','phase','planned_base_specs_fingerprint','implementation_base_commit','adopted_preexisting_paths','implementation_baselined_at','current_step','next_step'],v3=['schema_version','phase','planned_base_specs_fingerprint','planned_change_fingerprint','planned_tdd_policy_sha256','planning_approved_at','implementation_base_commit','adopted_preexisting_paths','implementation_baselined_at','current_step','next_step'],v4=[...v3.slice(0,5),'planned_integration_completeness_sha256',...v3.slice(5)],allowed=d.schema_version===2?v2:d.schema_version===3?v3:d.schema_version===4?v4:null;if(!st.isFile()||st.isSymbolicLink()||!allowed||Object.keys(d).some(k=>!allowed.includes(k))||allowed.some(k=>!(k in d))||'active_change'in d||!Array.isArray(d.adopted_preexisting_paths))throw Error('invalid local snapshot schema');if(d.implementation_base_commit&&adopted.some(x=>!d.adopted_preexisting_paths.includes(x)))throw Error('cannot adopt new paths after implementation starts');if(planned){if(d.implementation_base_commit&&refresh!=='1')throw Error('implementation already started; use explicit planning refresh');if(refresh==='1'&&!d.implementation_base_commit)throw Error('planning refresh requires an immutable implementation base');if(refresh!=='1'&&d.planned_base_specs_fingerprint&&d.planned_base_specs_fingerprint!==planned)throw Error('planned baseline is immutable');d.planned_base_specs_fingerprint=planned;if(d.schema_version>=3){if(!plannedChange||!plannedPolicy)throw Error('planning and TDD fingerprints required');d.planned_change_fingerprint=plannedChange;d.planned_tdd_policy_sha256=plannedPolicy;if(d.schema_version===4){if(!plannedIntegration)throw Error('Integration Completeness fingerprint required');d.planned_integration_completeness_sha256=plannedIntegration}d.planning_approved_at=new Date().toISOString().replace('.000Z','Z')}}if(base){if(!d.planned_base_specs_fingerprint||d.planned_base_specs_fingerprint!==currentBase)throw Error('planned base specs missing or stale');if(d.schema_version>=3&&(d.planned_change_fingerprint!==currentChange||d.planned_tdd_policy_sha256!==currentPolicy))throw Error('approved planning or TDD policy stale');if(d.schema_version===4&&d.planned_integration_completeness_sha256!==currentIntegration)throw Error('approved Integration Completeness policy stale');if(d.implementation_base_commit&&d.implementation_base_commit!==base)throw Error('implementation base already frozen');d.implementation_base_commit=base;d.implementation_baselined_at=d.implementation_baselined_at||new Date().toISOString().replace('.000Z','Z');d.phase='implementing'}if(phase)d.phase=phase;if(current)d.current_step=current;if(next)d.next_step=next;d.adopted_preexisting_paths=[...new Set([...d.adopted_preexisting_paths,...adopted])].sort();const t=path.join(path.dirname(file),'.snapshot-'+process.pid+'-'+Date.now());fs.writeFileSync(t,JSON.stringify(d,null,2)+'\n',{mode:0o644,flag:'wx'});fs.renameSync(t,file);
NODE
fi
harness_atomic_json_update ai_snapshot.json "${args[@]}"; echo 'Snapshot updated without changing the active selector.'
